}

.ce-exact-page.ce-exact-page.ce-exact-page { font-family: 'Montserrat', sans-serif; background: var(--charcoal); color: var(--text-light); line-height: 1.7; overflow-x: hidden; }


.ce-exact-page.ce-exact-page.ce-exact-page .eyebrow {
  display: inline-flex; align-items: center; gap: 12px;
