  color: var(--mustard); font-weight: 600; margin-bottom: 16px !important;
}
.ce-exact-page.ce-exact-page.ce-exact-page .eyebrow::before { content: ''; width: 28px; height: 1px; background: var(--mustard); }
.ce-exact-page.ce-exact-page.ce-exact-page .section-title {
  font-family: 'Playfair Display', serif;
  font-size: clamp(30px, 4vw, 48px); font-weight: 700; line-height: 1.1; margin-bottom: 12px !important;
}
.ce-exact-page.ce-exact-page.ce-exact-page .section-title em { font-style: italic; font-weight: 400; }
.ce-exact-page.ce-exact-page.ce-exact-page .rule { width: 56px; height: 2px; background: linear-gradient(to right, var(--mustard), var(--fendi)); margin-top: 20px !important; }

.ce-exact-page.ce-exact-page.ce-exact-page .btn-wa {
  background: var(--wa); color: #fff;
  padding: 16px 32px; font-size: 11px; letter-spacing: 2px;
  text-transform: uppercase; font-weight: 600; text-decoration: none;
  display: inline-flex; align-items: center; gap: 10px;
  font-family: 'Montserrat', sans-serif; transition: background 0.2s; border: none; cursor: pointer;
}
.ce-exact-page.ce-exact-page.ce-exact-page .btn-wa:hover { background: #1fb155; }
.ce-exact-page.ce-exact-page.ce-exact-page .btn-wa i { font-size: 18px; }
.ce-exact-page.ce-exact-page.ce-exact-page .btn-mustard {
  background: var(--mustard); color: #fff;
  padding: 15px 30px; font-size: 11px; letter-spacing: 2px;
  text-transform: uppercase; font-weight: 600; text-decoration: none;
  display: inline-flex; align-items: center; gap: 8px;
  font-family: 'Montserrat', sans-serif; transition: background 0.2s; border: none; cursor: pointer;
}
.ce-exact-page.ce-exact-page.ce-exact-page .btn-mustard:hover { background: #d9a820; }
.ce-exact-page.ce-exact-page.ce-exact-page .btn-ghost {
  border: 1px solid var(--fendi); color: var(--fendi);
  padding: 14px 28px; font-size: 11px; letter-spacing: 2px;
  text-transform: uppercase; font-weight: 500; text-decoration: none;
  display: inline-flex; align-items: center; gap: 8px;
  font-family: 'Montserrat', sans-serif; background: transparent; cursor: pointer; transition: all 0.2s;
}
.ce-exact-page.ce-exact-page.ce-exact-page .btn-ghost:hover { background: var(--fendi); color: var(--dark); }


.ce-exact-page.ce-exact-page.ce-exact-page .navbar {
  background: var(--dark); padding: 18px var(--pad);
  display: flex; align-items: center; justify-content: space-between;
  border-bottom: 1px solid rgba(194,165,122,0.12);
  position: sticky; top: 0; z-index: 100;
}
.ce-exact-page.ce-exact-page.ce-exact-page .navbar-logo { display: flex; align-items: center; gap: 12px; text-decoration: none; }
.ce-exact-page.ce-exact-page.ce-exact-page .navbar-logo img { height: 38px; object-fit: contain; }
.ce-exact-page.ce-exact-page.ce-exact-page .logo-name { font-family: 'Italiana', serif; font-size: 20px; color: var(--fendi); letter-spacing: 2px; }
.ce-exact-page.ce-exact-page.ce-exact-page .logo-tag { font-size: 8px; letter-spacing: 3px; text-transform: uppercase; color: rgba(194,165,122,0.45); }
.ce-exact-page.ce-exact-page.ce-exact-page .navbar-nav { display: flex; gap: 32px; list-style: none; }
.ce-exact-page.ce-exact-page.ce-exact-page .navbar-nav a { font-size: 11px; letter-spacing: 2px; text-transform: uppercase; color: var(--text-muted); text-decoration: none; transition: color 0.2s; }
.ce-exact-page.ce-exact-page.ce-exact-page .navbar-nav a:hover, .ce-exact-page.ce-exact-page.ce-exact-page .navbar-nav .active { color: var(--mustard); }
.ce-exact-page.ce-exact-page.ce-exact-page .navbar-wa {
