  font-size: 10px; letter-spacing: 2px; text-transform: uppercase;
  font-weight: 600; text-decoration: none; display: flex; align-items: center; gap: 7px;
  transition: background 0.2s;
}
.ce-exact-page.ce-exact-page.ce-exact-page .navbar-wa:hover { background: #1fb155; }


.ce-exact-page.ce-exact-page.ce-exact-page .hero {
  background: var(--dark); min-height: 55vh;
  display: flex; flex-direction: column; justify-content: center;
  padding: 70px var(--pad) 50px;
  position: relative; overflow: hidden;
}
.ce-exact-page.ce-exact-page.ce-exact-page .hero-left {
  position: relative; z-index: 2; max-width: 100%;
}
.ce-exact-page.ce-exact-page.ce-exact-page .hero-bg {
  position: absolute; bottom: -40px; right: -20px;
  font-family: 'Italiana', serif; font-size: clamp(160px, 22vw, 320px);
  color: transparent; -webkit-text-stroke: 1px rgba(194,165,122,0.04);
  pointer-events: none; line-height: 1; user-select: none; white-space: nowrap;
}
.ce-exact-page.ce-exact-page.ce-exact-page .hero-h {
