  color: var(--fendi);
}
.ce-exact-page.ce-exact-page.ce-exact-page .hero-sub-italic { font-family: 'Playfair Display', serif; font-size: clamp(16px, 2vw, 22px); font-style: italic; color: var(--text-muted); margin-bottom: 24px !important; }
.ce-exact-page.ce-exact-page.ce-exact-page .hero-desc { font-size: 14px; font-weight: 300; color: var(--text-muted); line-height: 1.9; max-width: 560px; margin-bottom: 36px !important; }
.ce-exact-page.ce-exact-page.ce-exact-page .hero-btns { display: flex; gap: 12px; flex-wrap: wrap; }


.ce-exact-page.ce-exact-page.ce-exact-page .hero-search {
