.ce-exact-page.ce-exact-page.ce-exact-page .hero-stat-num { font-family: 'Italiana', serif; font-size: 40px; color: var(--mustard); line-height: 1; }
.ce-exact-page.ce-exact-page.ce-exact-page .hero-stat-label { font-size: 10px; letter-spacing: 2px; text-transform: uppercase; color: var(--text-muted); margin-top: 4px !important; }
