.ce-exact-page.ce-exact-page.ce-exact-page *, .ce-exact-page.ce-exact-page.ce-exact-page *::before, .ce-exact-page.ce-exact-page.ce-exact-page *::after { box-sizing: border-box; margin: 0 !important; padding: 0; }

.ce-exact-page.ce-exact-page.ce-exact-page {
  --fendi:        #c2a57a;
  --fendi-dark:   #9e7d4e;
  --fendi-bg:     #ede0cc;
  --fendi-pale:   #f5ede0;
  --mustard:      #c8960c;
  --mustard-deep: #8f6a08;
  --dark:         #1e1608;
  --charcoal:     #2e2410;
  --charcoal2:    #3a2e16;
  --off-dark:     #463820;
  --text-light:   #f5eed8;
  --text-muted:   #a89370;
  --pad: 90px;
  --gap: 60px;
}

.ce-exact-page.ce-exact-page.ce-exact-page {
  font-family: 'Montserrat', sans-serif;
  background: var(--charcoal);
  color: var(--text-light);
  line-height: 1.7;
  overflow-x: hidden;
}


.ce-exact-page.ce-exact-page.ce-exact-page .eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 14px;
  font-size: 10px;
  letter-spacing: 5px;
  text-transform: uppercase;
  color: var(--mustard);
  font-weight: 600;
  margin-bottom: 18px !important;
}
.ce-exact-page.ce-exact-page.ce-exact-page .eyebrow::before {
  content: '';
  width: 32px; height: 1px;
  background: var(--mustard);
}
.ce-exact-page.ce-exact-page.ce-exact-page .block-title {
  font-family: 'Playfair Display', serif;
  font-size: clamp(34px, 4.5vw, 52px);
  font-weight: 700;
  line-height: 1.1;
  margin-bottom: 18px !important;
}
.ce-exact-page.ce-exact-page.ce-exact-page .block-title em { font-style: italic; font-weight: 400; }
.ce-exact-page.ce-exact-page.ce-exact-page .block-sub {
  font-size: 14px;
  font-weight: 300;
  line-height: 1.9;
  max-width: 580px;
  color: var(--text-muted);
}
.ce-exact-page.ce-exact-page.ce-exact-page .rule {
  width: 64px; height: 2px;
  background: linear-gradient(to right, var(--mustard), var(--fendi));
  margin-top: 24px !important;
}


.ce-exact-page.ce-exact-page.ce-exact-page .navbar {
  background: var(--dark);
  padding: 20px var(--pad);
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid rgba(194,165,122,0.12);
  position: sticky;
  top: 0;
  z-index: 100;
}
.ce-exact-page.ce-exact-page.ce-exact-page .navbar-logo {
  display: flex;
  align-items: center;
  gap: 14px;
  text-decoration: none;
}
.ce-exact-page.ce-exact-page.ce-exact-page .logo-symbol {
  width: 40px; height: 40px;
  object-fit: contain;
}
.ce-exact-page.ce-exact-page.ce-exact-page .logo-text-wrap { display: flex; flex-direction: column; line-height: 1.1; }
.ce-exact-page.ce-exact-page.ce-exact-page .logo-name { font-family: 'Italiana', serif; font-size: 22px; color: var(--fendi); letter-spacing: 2px; }
.ce-exact-page.ce-exact-page.ce-exact-page .logo-tagline { font-size: 8.5px; letter-spacing: 3px; text-transform: uppercase; color: rgba(194,165,122,0.5); }
.ce-exact-page.ce-exact-page.ce-exact-page .navbar-nav { display: flex; gap: 36px; list-style: none; }
.ce-exact-page.ce-exact-page.ce-exact-page .navbar-nav a { font-size: 11px; letter-spacing: 2px; text-transform: uppercase; color: var(--text-muted); text-decoration: none; font-weight: 400; transition: color 0.25s; }
.ce-exact-page.ce-exact-page.ce-exact-page .navbar-nav a:hover, .ce-exact-page.ce-exact-page.ce-exact-page .navbar-nav .active { color: var(--mustard); }
.ce-exact-page.ce-exact-page.ce-exact-page .navbar-cta {
  background: var(--mustard);
  color: #fff;
  padding: 11px 28px;
  font-size: 10px;
  letter-spacing: 2.5px;
  text-transform: uppercase;
  font-weight: 600;
  text-decoration: none;
  transition: background 0.25s;
}
.ce-exact-page.ce-exact-page.ce-exact-page .navbar-cta:hover { background: #d9a820; }


.ce-exact-page.ce-exact-page.ce-exact-page .btn-mustard {
  background: var(--mustard);
  color: #fff;
  padding: 17px 40px;
  font-size: 11px;
  letter-spacing: 3px;
  text-transform: uppercase;
  font-weight: 600;
  text-decoration: none;
  border: none;
  cursor: pointer;
  transition: background 0.25s;
  font-family: 'Montserrat', sans-serif;
  display: inline-block;
}
.ce-exact-page.ce-exact-page.ce-exact-page .btn-mustard:hover { background: #d9a820; }
.ce-exact-page.ce-exact-page.ce-exact-page .btn-ghost {
  border: 1px solid var(--fendi);
  color: var(--fendi);
  padding: 16px 36px;
  font-size: 11px;
  letter-spacing: 3px;
  text-transform: uppercase;
  font-weight: 500;
  text-decoration: none;
  background: transparent;
  cursor: pointer;
  transition: all 0.25s;
  font-family: 'Montserrat', sans-serif;
  display: inline-block;
}
.ce-exact-page.ce-exact-page.ce-exact-page .btn-ghost:hover { background: var(--fendi); color: var(--dark); }


.ce-exact-page.ce-exact-page.ce-exact-page .hero {
  min-height: 100vh;
  background: var(--dark);
  display: flex;
  flex-direction: column;
  justify-content: center;
  position: relative;
  overflow: hidden;
  padding: 120px var(--pad) 100px;
}
.ce-exact-page.ce-exact-page.ce-exact-page .hero-bg-word {
  position: absolute;
  bottom: -40px; right: 0;
  font-family: 'Italiana', serif;
