}

.ce-accordion .elementor-accordion-icon {
  min-width: 22px;
}

.ce-cta .ce-heading {
  max-width: 860px;
  margin: 12px 0 16px;
}

.ce-cta .ce-copy {
  max-width: 760px;
  margin-bottom: 24px;
}

.ce-cta .ce-button {
  width: auto !important;
  margin: 0 12px 12px 0;
}

.ce-video-section > .elementor-container {
  align-items: center;
  gap: 64px;
}

.ce-video-section > .elementor-container > .elementor-column {
